        int32 &= 0x7FFFFFFF;
        p = unsafe { p.add(4) };
    } else {
        p = unsafe { p.add(1) };
    }

    size = int32;

    if !plimit.is_null() && p > plimit {
        return 0;
    }

    unsafe {
        int32 = *p as i32;
    }

    if int32 & 0x80 != 0 {
        if !plimit.is_null() && unsafe { p.add(std::mem::size_of::<i32>() - 1) } > plimit {
            return 0;
        }
        copy_be32(&mut int32 as *mut i32 as *mut U32, p as *const U32);
        int32 &= 0x7FFFFFFF;
        p = unsafe { p.add(4) };
    } else {
        p = unsafe { p.add(1) };
    }

    count = int32;

