        return None;
    }

    let byte = p[0];
    *p = &p[1..];
    let storage_type = byte & 0xE0;

    if byte & 0x10 != 0 {
        *p = &p[1..];
    }

    match storage_type {
        0x00 => {}
        0x20 => {
            *p = &p[1..];
        }
        0x40 => {
            *p = &p[2..];
        }
        0x60 => {
            *p = &p[4..];
        }
        0x80 => {
            *p = &p[8..];
        }
        0xC0 | 0xA0 => {
            if p.len() > plimit.len() {
                return None;
            }
            let mut data_size = p[0] as usize;
            *p = &p[1..];
            if data_size & 0x80 != 0 {
                if p.len() < std::mem::size_of::<u32>() {
                    return None;
                }
                let mut data_size_u32 = 0u32;
                copy_be32(&mut data_size_u32, unsafe { &*(p.as_ptr() as *const U32) });
                data_size = (data_size_u32 & 0x7FFFFFFF) as usize;
                *p = &p[4..];
            }
            *p = &p[data_size..];
            if storage_type == 0xA0 {
                *p = &p[1..];
            }
        }
        0xE0 => {
            if p.len() > plimit.len() {
                return None;
            }
            let mut data_size = p[0] as usize;
            *p = &p[1..];
            if data_size & 0x80 != 0 {
                if p.len() < std::mem::size_of::<u32>() {
                    return None;
                }
                let mut data_size_u32 = 0u32;
                copy_be32(&mut data_size_u32, unsafe { &*(p.as_ptr() as *const U32) });
                data_size = (data_size_u32 & 0x7FFFFFFF) as usize;
            }
            data_size -= 1;
            *p = &p[data_size..];
        }
        _ => return None,
    }

    if p.len() > plimit.len() {
        return None;
    }

    Some(p)
}

pub fn read_map_id(pp: &mut &[u8], plimit: &[u8]) -> i32 {
    let mut p = *pp;
    let c = p[0];
    p = &p[1..];
    let mut id;
    let mut sign;
    let mut type_byte;

    if c & 0x80 != 0 {
        let extra_bytes = ((c & 0x60) >> 5) + 1;
        if p.len() < extra_bytes || p.as_ptr().wrapping_add(extra_bytes) > plimit.as_ptr() {
            *pp = &p[extra_bytes..];
            return 0;
        }
    }

    type_byte = c & 0xE0;
    sign = c & 0x10;

    if c & 0x80 == 0 {
        sign = c & 0x40;
        id = (c & 0x3F) as i32;
    } else if type_byte == 0x80 {
        id = (c & 0x0F) as i32;
        id = (id << 8) | p[0] as i32;
        p = &p[1..];
    } else if type_byte == 0xA0 {
        id = (c & 0x0F) as i32;
        id = (id << 8) | p[0] as i32;
        p = &p[1..];
        id = (id << 8) | p[0] as i32;
        p = &p[1..];
    } else if type_byte == 0xC0 {
        id = (c & 0x0F) as i32;
        id = (id << 8) | p[0] as i32;
        p = &p[1..];
        id = (id << 8) | p[0] as i32;
        p = &p[1..];
        id = (id << 8) | p[0] as i32;
        p = &p[1..];
    } else if type_byte == 0xE0 {
        let mut id_u32: U32 = 0;
        copy_be32(&mut id_u32, unsafe { &*(p.as_ptr() as *const U32) });
        id = id_u32 as i32;
        p = &p[4..];
    } else {
        *pp = &plimit[2..];
        return 0;
    }

    if sign != 0 {
        id = -id;
    }

    *pp = p;
    id
}

