pub fn binn_free(item: &mut BinnStruct) {
    if item.writable && !item.pre_allocated {
        if let Some(free_fn) = unsafe { free_fn } {
            free_fn(item.pbuf);
        }
    }
    if let Some(freefn) = item.freefn {
        freefn(item.ptr);
    }
    if item.allocated {
        if let Some(free_fn) = unsafe { free_fn } {
            free_fn(item as *mut _ as *mut c_void);
        }
    } else {
        unsafe {
            ptr::write_bytes(item as *mut _ as *mut u8, 0, std::mem::size_of::<BinnStruct>());
        }
        item.header = 0x1F22B11F;
    }
}

pub fn check_allocation(item: &mut BinnStruct, add_size: i32) -> Bool {
    let mut alloc_size: i32;
    let mut ptr: *mut std::ffi::c_void;

    if item.used_size + add_size > item.alloc_size {
        if item.pre_allocated != 0 {
            return 0;
        }
        alloc_size = calc_allocation(item.used_size + add_size, item.alloc_size);
        unsafe {
            if let Some(realloc_fn) = REALLOC_FN {
                ptr = realloc_fn(item.pbuf as *mut u8, alloc_size as usize) as *mut std::ffi::c_void;
            } else {
                return 0;
            }
        }
        if ptr.is_null() {
            return 0;
        }
        item.pbuf = ptr;
        item.alloc_size = alloc_size;
    }
    1
}

pub fn binn_save_header(item: &mut BinnStruct) -> Bool {
    if item.pbuf.is_null() {
        return 0;
    }

    let mut p = unsafe { (item.pbuf as *mut u8).add(9) };
    let mut size = item.used_size - 9 + 3;

    if item.count > 127 {
        p = unsafe { p.sub(4) };
        size += 3;
        let int32 = item.count | 0x80000000;
        copy_be32(unsafe { &mut *(p as *mut U32) }, &int32);
    } else {
        p = unsafe { p.sub(1) };
        unsafe { *p = item.count as u8 };
    }

    if size > 127 {
        p = unsafe { p.sub(4) };
        size += 3;
        let int32 = size | 0x80000000;
        copy_be32(unsafe { &mut *(p as *mut U32) }, &int32);
    } else {
        p = unsafe { p.sub(1) };
        unsafe { *p = size as u8 };
    }

    p = unsafe { p.sub(1) };
    unsafe { *p = item.type_ as u8 };

    item.ptr = p as *mut std::ffi::c_void;
    item.size = size;
    item.dirty = 0;

    1
}

