}

use std::ffi::CString;
use std::os::raw::c_char;

pub fn binn_get_str(value: &mut BinnStruct) -> Option<*mut c_char> {
    let mut vint: Int64 = 0;
    let mut buf = [0u8; 128];

    if value.is_null() {
        return None;
    }

    if type_family(value.type_) == 0xf2 {
        if copy_int_value(value.ptr as *const u8, &mut vint as *mut _ as *mut u8, value.type_ as u8, 0x81) == 0 {
            return None;
        }
        let formatted = format!("{}", vint);
        buf[..formatted.len()].copy_from_slice(formatted.as_bytes());
        goto_loc_convert_value(value, &buf);
    }

    match value.type_ {
        0x62 => {
            value.vdouble = value.vfloat as f64;
        }
        0x82 => {
            let formatted = format!("{}", value.vdouble);
            buf[..formatted.len()].copy_from_slice(formatted.as_bytes());
            goto_loc_convert_value(value, &buf);
        }
        0xA0 => {
            return Some(value.ptr as *mut c_char);
        }
        0x80061 => {
            let formatted = if value.vbool { "true" } else { "false" };
            buf[..formatted.len()].copy_from_slice(formatted.as_bytes());
            goto_loc_convert_value(value, &buf);
        }
        _ => return None,
    }

    None
}

