pub fn binn_type(ptr: *const std::ffi::c_void) -> i32 {
    match binn_get_ptr_type(ptr as *const u32) {
        1 => {
            let item = unsafe { &*(ptr as *const BinnStruct) };
            item.type_
        }
        2 => binn_buf_type(ptr as *const u8),
        _ => -1,
    }
}

pub fn binn_count(ptr: *const std::ffi::c_void) -> i32 {
    match binn_get_ptr_type(ptr as *const u32) {
        1 => {
            let item = unsafe { &*(ptr as *const BinnStruct) };
            item.count
        }
        2 => binn_buf_count(ptr as *const u8),
        _ => -1,
    }
}

pub fn binn_size(ptr: *const std::ffi::c_void) -> i32 {
    let item: &mut BinnStruct;
    match binn_get_ptr_type(ptr as *const u32) {
        1 => {
            item = unsafe { &mut *(ptr as *mut BinnStruct) };
            if item.writable && item.dirty {
                binn_save_header(item);
            }
            item.size
        }
        2 => binn_buf_size(ptr as *const u8),
        _ => 0,
    }
}

pub fn binn_list_next(iter: &mut BinnIter, value: &mut BinnStruct) -> Bool {
    if iter.pnext.is_empty() || iter.pnext.as_ptr() > iter.plimit.as_ptr() || iter.current > iter.count || iter.type_ != 0xE0 {
        return 0;
    }
    iter.current += 1;
    if iter.current > iter.count {
        return 0;
    }
    let pnow = iter.pnext;
    iter.pnext = match advance_data_pos(&mut iter.pnext, iter.plimit) {
        Some(new_pnext) => new_pnext,
        None => return 0,
    };
    if iter.pnext.as_ptr() < pnow.as_ptr() {
        return 0;
    }
    get_value(pnow.as_ptr() as *mut u8, value)
}

pub fn binn_read_next_pair(
    expected_type: i32,
    iter: &mut BinnIter,
    pid: Option<&mut i32>,
    pkey: Option<&mut [u8]>,
    value: &mut BinnStruct,
) -> Bool {
    let mut int32: i32;
    let mut id: i32;
    let mut p: &[u8];
    let mut key: &[u8];
    let mut len: u16;

    if iter.pnext.is_empty() || iter.pnext.as_ptr() > iter.plimit.as_ptr() || iter.current > iter.count || iter.type_ != expected_type {
        return 0;
    }

    iter.current += 1;
    if iter.current > iter.count {
        return 0;
    }

    p = iter.pnext;

    match expected_type {
        0xE1 => {
            int32 = read_map_id(&mut p, iter.plimit);
            if p.as_ptr() > iter.plimit.as_ptr() {
                return 0;
            }
            id = int32;
            if let Some(pid_ref) = pid {
                *pid_ref = id;
            }
        }
        0xE2 => {
            len = p[0] as u16;
            p = &p[1..];
            key = &p[..len as usize];
            p = &p[len as usize..];
            if p.as_ptr() > iter.plimit.as_ptr() {
                return 0;
            }
            if let Some(pkey_ref) = pkey {
                pkey_ref[..len as usize].copy_from_slice(key);
                pkey_ref[len as usize] = 0;
            }
        }
        _ => {}
    }

    iter.pnext = match advance_data_pos(&mut p, iter.plimit) {
        Some(new_pnext) => new_pnext,
        None => return 0,
    };

    if iter.pnext.as_ptr() < p.as_ptr() {
        return 0;
    }

    get_value(p.as_ptr() as *mut u8, value)
}

pub fn binn_release(item: &mut BinnStruct) -> *mut c_void {
    if item as *const _ == ptr::null() {
        return ptr::null_mut();
    }

    let mut data = binn_ptr(item as *const _ as *const u32);

    if data > item.pbuf {
        unsafe {
            ptr::copy(item.pbuf, data, item.size as usize);
        }
        data = item.pbuf;
    }

    if item.allocated {
        unsafe {
            if let Some(free_fn) = free_fn {
                free_fn(item as *mut _ as *mut c_void);
            }
        }
    } else {
        unsafe {
            ptr::write_bytes(item as *mut _, 0, 1);
        }
        item.header = 0x1F22B11F;
    }

    data
}

pub fn binn_is_valid_ex(
    ptr: *const u32,
    ptype: Option<&mut i32>,
    pcount: Option<&mut i32>,
    psize: Option<&mut i32>,
) -> Bool {
    let mut type_: i32 = 0;
    let mut count: i32 = 0;
    let mut size: i32 = 0;
    let mut header_size: i32 = 0;
    let mut pbuf = unsafe { binn_ptr(ptr) };

    if pbuf.is_null() {
        return 0;
    }

    if let Some(psize) = psize {
        if *psize > 0 {
            size = *psize;
        }
    }

    if is_valid_binn_header(pbuf as *const u8, Some(&mut type_), Some(&mut count), Some(&mut size), Some(&mut header_size)) == 0 {
        return 0;
    }

    if let Some(psize) = psize {
        if *psize > 0 && size != *psize {
            return 0;
        }
    }

    if let Some(pcount) = pcount {
        if *pcount > 0 && count != *pcount {
            return 0;
        }
    }

    if let Some(ptype) = ptype {
        if *ptype != 0 && type_ != *ptype {
            return 0;
        }
    }

    let mut p = unsafe { std::slice::from_raw_parts(pbuf as *const u8, size as usize) };
    let base = p;
    let plimit = &p[size as usize..];
    p = &p[header_size as usize..];

    for _ in 0..count {
        match type_ {
            0xE2 => {
                let len = p[0];
                p = &p[1..];
                p = &p[len as usize..];
            }
            0xE1 => {
                read_map_id(&mut p, plimit);
            }
            _ => {}
        }

        if let Some(new_p) = advance_data_pos(&mut p, plimit) {
            p = new_p;
        } else {
            return 0;
        }

        if p.as_ptr() < base.as_ptr() {
            return 0;
        }
    }

    if let Some(ptype) = ptype {
        if *ptype == 0 {
            *ptype = type_;
        }
    }

    if let Some(pcount) = pcount {
        if *pcount == 0 {
            *pcount = count;
        }
    }

    if let Some(psize) = psize {
        if *psize == 0 {
            *psize = size;
        }
    }

    1
}

pub fn binn_list_get_value(ptr: *mut std::ffi::c_void, pos: i32, value: &mut BinnStruct) -> Bool {
    let mut type_: i32 = 0;
    let mut count: i32 = 0;
    let mut size: i32 = 0;
    let mut header_size: i32 = 0;

    let ptr = binn_ptr(ptr as *const u32);
    if ptr.is_null() || value as *mut BinnStruct as *mut std::ffi::c_void == std::ptr::null_mut() {
        return 0;
    }

    if is_valid_binn_header(ptr as *const u8, Some(&mut type_), Some(&mut count), Some(&mut size), Some(&mut header_size)) == 0 {
        return 0;
    }

    if type_ != 0xE0 {
        return 0;
    }

    if count == 0 {
        return 0;
    }

    if pos <= 0 || pos > count {
        return 0;
    }

    let mut pos = pos - 1;
    let mut p = ptr as *mut u8;
    let base = p;
    let plimit = unsafe { p.add(size as usize) };
    p = unsafe { p.add(header_size as usize) };

    for _ in 0..pos {
        p = match advance_data_pos(&mut std::slice::from_raw_parts_mut(p, plimit as usize - p as usize), std::slice::from_raw_parts(plimit, 0)) {
            Some(new_p) => new_p.as_ptr() as *mut u8,
            None => return 0,
        };
        if p.is_null() || p < base {
            return 0;
        }
    }

    get_value(p, value)
}

pub fn binn_map_get_value(ptr: *const u32, id: i32, value: &mut BinnStruct) -> Bool {
    let mut type_: i32 = 0;
    let mut count: i32 = 0;
    let mut size: i32 = 0;
    let mut header_size: i32 = 0;
    let mut p: Option<&[u8]>;

    let ptr = binn_ptr(ptr);
    if ptr.is_null() || value.is_null() {
        return 0;
    }

    if is_valid_binn_header(ptr as *const u8, Some(&mut type_), Some(&mut count), Some(&mut size), Some(&mut header_size)) == 0 {
        return 0;
    }

    if type_ != 0xE1 {
        return 0;
    }

    if count == 0 {
        return 0;
    }

    p = search_for_id(&mut unsafe { std::slice::from_raw_parts(ptr as *const u8, size as usize) }, header_size as usize, size as usize, count as usize, id);
    if p.is_none() {
        return 0;
    }

    get_value(p.unwrap().as_ptr() as *mut u8, value)
}

pub fn binn_object_get_value(
    ptr: *const u32,
    key: &str,
    value: &mut BinnStruct,
) -> Bool {
    let mut type_: i32 = 0;
    let mut count: i32 = 0;
    let mut size: i32 = 0;
    let mut header_size: i32 = 0;
    let mut p: *mut u8;

    let ptr = binn_ptr(ptr);
    if ptr.is_null() || key.is_empty() || value as *mut _ == std::ptr::null_mut() {
        return 0;
    }

    if is_valid_binn_header(ptr as *const u8, Some(&mut type_), Some(&mut count), Some(&mut size), Some(&mut header_size)) == 0 {
        return 0;
    }

    if type_ != 0xE2 {
        return 0;
    }

    if count == 0 {
        return 0;
    }

    p = ptr as *mut u8;
    let key_search_result = search_for_key(
        unsafe { std::slice::from_raw_parts(p, size as usize) },
        header_size as usize,
        size as usize,
        count as usize,
        key,
    );

    if key_search_result.is_none() {
        return 0;
    }

    p = key_search_result.unwrap().as_ptr() as *mut u8;
    get_value(p, value)
}

pub fn binn_iter_init(iter: &mut BinnIter, ptr: *const u32, expected_type: i32) -> Bool {
    let mut type_: i32 = 0;
    let mut count: i32 = 0;
    let mut size: i32 = 0;
    let mut header_size: i32 = 0;

    let ptr = binn_ptr(ptr);
    if ptr.is_null() || iter.pnext.is_empty() {
        return 0;
    }

    unsafe {
        ptr::write_bytes(iter, 0, 1);
    }

    if is_valid_binn_header(ptr as *const u8, Some(&mut type_), Some(&mut count), Some(&mut size), Some(&mut header_size)) == 0 {
        return 0;
    }

    if type_ != expected_type {
        return 0;
    }

    iter.plimit = unsafe { slice::from_raw_parts(ptr as *const u8, size as usize - 1) };
    iter.pnext = unsafe { slice::from_raw_parts(ptr as *const u8, header_size as usize) };
    iter.count = count;
    iter.current = 0;
    iter.type_ = type_;

    1
}

pub fn binn_read_pair(
    expected_type: i32,
    ptr: *const u32,
    pos: i32,
    pid: Option<&mut i32>,
    pkey: Option<&mut [u8]>,
    value: &mut BinnStruct,
) -> Bool {
    let mut type_: i32 = 0;
    let mut count: i32 = 0;
    let mut size: i32 = 0;
    let mut header_size: i32 = 0;
    let mut id: i32 = 0;
    let mut counter: i32 = 0;
    let mut key: Option<&[u8]> = None;
    let mut len: u8 = 0;

    let ptr = binn_ptr(ptr);
    if is_valid_binn_header(ptr as *const u8, Some(&mut type_), Some(&mut count), Some(&mut size), Some(&mut header_size)) == 0 {
        return 0;
    }
    if type_ != expected_type || count == 0 || pos < 1 || pos > count {
        return 0;
    }

    let mut p = unsafe { std::slice::from_raw_parts(ptr as *const u8, size as usize) };
    let base = p;
    let plimit = &p[size as usize - 1..];
    p = &p[header_size as usize..];

    for _ in 0..count {
        match type_ {
            0xE1 => {
                let int32 = read_map_id(&mut p, plimit);
                if p.is_empty() {
                    return 0;
                }
                id = int32;
            }
            0xE2 => {
                len = p[0];
                p = &p[1..];
                if p.is_empty() {
                    return 0;
                }
                key = Some(&p[..len as usize]);
                p = &p[len as usize..];
                if p.is_empty() {
                    return 0;
                }
            }
            _ => {}
        }
        counter += 1;
        if counter == pos {
            break;
        }
        p = match advance_data_pos(&mut p, plimit) {
            Some(new_p) => new_p,
            None => return 0,
        };
        if p.as_ptr() < base.as_ptr() {
            return 0;
        }
    }

    match type_ {
        0xE1 => {
            if let Some(pid) = pid {
                *pid = id;
            }
        }
        0xE2 => {
            if let Some(pkey) = pkey {
                if let Some(key) = key {
                    pkey[..len as usize].copy_from_slice(key);
                    pkey[len as usize] = 0;
                }
            }
        }
        _ => {}
    }

    get_value(p.as_mut_ptr(), value)
}

pub fn add_value(item: &mut BinnStruct, type_: i32, pvalue: *mut std::ffi::c_void, size: i32) -> Bool {
    let mut int32: i32;
    let mut arg_size: i32;
    let mut storage_type: i32 = 0;
    let mut extra_type: i32 = 0;
    let mut p = std::ptr::null_mut::<u8>();

    if binn_get_type_info(type_, Some(&mut storage_type), Some(&mut extra_type)) == 0 {
        return 0;
    }

    if pvalue.is_null() {
        match storage_type {
            0x00 => {}
            0xC0 | 0xA0 => if size == 0 {},
            _ => return 0,
        }
    }

    if type_family(type_) == 0xf2 && item.disable_int_compression == 0 {
        pvalue = compress_int(&mut storage_type, &mut type_, pvalue);
    }

    match storage_type {
        0x00 => {
            arg_size = 0;
        }
        0x20 => {
            arg_size = 1;
        }
        0x40 => {
            arg_size = 2;
        }
        0x60 => {
            arg_size = 4;
        }
        0x80 => {
            arg_size = 8;
        }
        0xC0 => {
            if size < 0 {
                return 0;
            }
            arg_size = size + 4;
        }
        0xA0 => {
            if size < 0 {
                return 0;
            }
            let size = if size == 0 {
                strlen2(unsafe { std::ffi::CStr::from_ptr(pvalue as *const i8) }.to_str().ok())
            } else {
                size as usize
            };
            arg_size = size as i32 + 5;
        }
        0xE0 => {
            if size <= 0 {
                return 0;
            }
            arg_size = size;
        }
        _ => return 0,
    }

    arg_size += 2;

    if check_allocation(item, arg_size) == 0 {
        return 0;
    }

    p = unsafe { item.pbuf.add(item.used_size as usize) } as *mut u8;

    if storage_type != 0xE0 {
        if type_ > 255 {
            let type16 = type_ as u16;
            copy_be16(unsafe { &mut *(p as *mut U16) }, &type16);
            p = unsafe { p.add(2) };
            item.used_size += 2;
        } else {
            unsafe {
                *p = type_ as u8;
            }
            p = unsafe { p.add(1) };
            item.used_size += 1;
        }
    }

    match storage_type {
        0x00 => {}
        0x20 => {
            unsafe {
                *(p as *mut i8) = *(pvalue as *const i8);
            }
            item.used_size += 1;
        }
        0x40 => {
            copy_be16(unsafe { &mut *(p as *mut U16) }, unsafe { &*(pvalue as *const U16) });
            item.used_size += 2;
        }
        0x60 => {
            copy_be32(unsafe { &mut *(p as *mut U32) }, unsafe { &*(pvalue as *const U32) });
            item.used_size += 4;
        }
        0x80 => {
            copy_be64(unsafe { &mut *(p as *mut [u8; 8]) }, unsafe { &*(pvalue as *const [u8; 8]) });
            item.used_size += 8;
        }
        0xC0 | 0xA0 => {
            if size > 127 {
                int32 = size | 0x80000000;
                copy_be32(unsafe { &mut *(p as *mut U32) }, &int32);
                p = unsafe { p.add(4) };
                item.used_size += 4;
            } else {
                unsafe {
                    *p = size as u8;
                }
                p = unsafe { p.add(1) };
                item.used_size += 1;
            }
            unsafe {
                std::ptr::copy_nonoverlapping(pvalue as *const u8, p, size as usize);
            }
            if storage_type == 0xA0 {
                p = unsafe { p.add(size as usize) };
                unsafe {
                    *p = 0;
                }
                size += 1;
            }
            item.used_size += size;
        }
        0xE0 => {
            unsafe {
                std::ptr::copy_nonoverlapping(pvalue as *const u8, p, size as usize);
            }
            item.used_size += size;
        }
    }

    item.dirty = 1;
    1
}

