pub fn binn_copy(old: *const c_void) -> *mut BinnStruct {
    let mut type_: i32 = 0;
    let mut count: i32 = 0;
    let mut size: i32 = 0;
    let mut header_size: i32 = 0;

    let old_ptr = binn_ptr(old as *const u32) as *const u8;

    if !is_valid_binn_header(
        old_ptr,
        Some(&mut type_),
        Some(&mut count),
        Some(&mut size),
        Some(&mut header_size),
    ) {
        return ptr::null_mut();
    }

    let item = binn_new(type_, size - header_size + 9, ptr::null_mut());

    if !item.is_null() {
        unsafe {
            let dest = ((*item).pbuf as *mut u8).add(9);
            ptr::copy_nonoverlapping(old_ptr.add(header_size), dest, (size - header_size) as usize);
            (*item).used_size = 9 + size - header_size;
            (*item).count = count;
        }
    }

    item
}

