pub fn binn_list_add_raw(item: &mut BinnStruct, type_: i32, pvalue: *mut std::ffi::c_void, size: i32) -> Bool {
    if item.is_null() || item.type_ != 0xE0 || item.writable == 0 {
        return 0;
    }
    if add_value(item, type_, pvalue, size) == 0 {
        return 0;
    }
    item.count += 1;
    1
}

pub fn binn_object_set_raw(
    item: &mut BinnStruct,
    key: &str,
    type_: i32,
    pvalue: *mut c_void,
    size: i32,
) -> Bool {
    if item.is_null() || item.type_ != 0xE2 || item.writable == 0 {
        return 0;
    }
    if key.is_empty() {
        return 0;
    }
    let int32 = key.len();
    if int32 > 255 {
        return 0;
    }
    let p = search_for_key(
        unsafe { slice::from_raw_parts(item.pbuf as *const u8, item.used_size as usize) },
        9,
        item.used_size as usize,
        item.count as usize,
        key,
    );
    if p.is_some() {
        return 0;
    }
    if check_allocation(item, 1 + int32 as i32) == 0 {
        return 0;
    }
    let p = unsafe { (item.pbuf as *mut u8).add(item.used_size as usize) };
    unsafe {
        *p = int32 as u8;
        ptr::copy_nonoverlapping(key.as_ptr(), p.add(1), int32);
    }
    item.used_size += int32 as i32 + 1;
    if add_value(item, type_, pvalue, size) == 0 {
        item.used_size -= int32 as i32 + 1;
        return 0;
    }
    item.count += 1;
    1
}

pub fn binn_map_set_raw(item: &mut BinnStruct, id: i32, type_: i32, pvalue: *mut std::ffi::c_void, size: i32) -> Bool {
    let mut base: *mut u8;
    let mut p: *mut u8;
    let sign: u8;
    let id_size: i32;

    if item.is_null() || item.type_ != 0xE1 || item.writable == 0 {
        return 0;
    }

    p = search_for_id(item.pbuf, 9, item.used_size as usize, item.count as usize, id);
    if p.is_some() {
        return 0;
    }

    if check_allocation(item, 5) == 0 {
        return 0;
    }

    p = base = unsafe { item.pbuf.offset(item.used_size as isize) as *mut u8 };
    sign = (id < 0) as u8;
    let mut id = id;
    if sign != 0 {
        id = -id;
    }

    unsafe {
        if id <= 0x3F {
            *p = (sign << 6) | id as u8;
            p = p.offset(1);
        } else if id <= 0xFFF {
            *p = 0x80 | (sign << 4) | ((id & 0xF00) >> 8) as u8;
            p = p.offset(1);
            *p = (id & 0xFF) as u8;
            p = p.offset(1);
        } else if id <= 0xFFFFF {
            *p = 0xA0 | (sign << 4) | ((id & 0xF0000) >> 16) as u8;
            p = p.offset(1);
            *p = ((id & 0xFF00) >> 8) as u8;
            p = p.offset(1);
            *p = (id & 0xFF) as u8;
            p = p.offset(1);
        } else if id <= 0xFFFFFFF {
            *p = 0xC0 | (sign << 4) | ((id & 0xF000000) >> 24) as u8;
            p = p.offset(1);
            *p = ((id & 0xFF0000) >> 16) as u8;
            p = p.offset(1);
            *p = ((id & 0xFF00) >> 8) as u8;
            p = p.offset(1);
            *p = (id & 0xFF) as u8;
            p = p.offset(1);
        } else {
            *p = 0xE0;
            p = p.offset(1);
            if sign != 0 {
                id = -id;
            }
            copy_be32(p as *mut U32, &id as *const i32 as *const U32);
            p = p.offset(4);
        }
    }

    id_size = p as i32 - base as i32;
    item.used_size += id_size;

    if add_value(item, type_, pvalue, size) == 0 {
        item.used_size -= id_size;
        return 0;
    }

    item.count += 1;
    return 1;
}

