        vuint64: 0,
        vchar: 0,
        vuchar: 0,
        vshort: 0,
        vushort: 0,
        vint: 0,
        vuint: 0,
        vfloat: 0.0,
        vdouble: 0.0,
        vbool: false,
        disable_int_compression: false,
    });

    if binn_object_next(iter, pkey, &mut *value) == false {
        unsafe {
            if let Some(free_fn) = free_fn {
                free_fn(Box::into_raw(value) as *mut std::ffi::c_void);
            }
        }
        return None;
    }

    value.allocated = true;
    Some(value)
}

pub fn binn_object_read_next(
    iter: &mut BinnIter,
    pkey: Option<&mut [u8]>,
    ptype: Option<&mut i32>,
    psize: Option<&mut i32>,
) -> *mut std::ffi::c_void {
    let mut value = BinnStruct {
        header: 0,
        allocated: false,
        writable: false,
        dirty: false,
        pbuf: std::ptr::null_mut(),
        pre_allocated: false,
        alloc_size: 0,
        used_size: 0,
        type_: 0,
        ptr: std::ptr::null_mut(),
        size: 0,
        count: 0,
        freefn: None,
        vint8: 0,
        vint16: 0,
        vint32: 0,
        vint64: 0,
        vuint8: 0,
        vuint16: 0,
        vuint32: 0,
        vuint64: 0,
        vchar: 0,
        vuchar: 0,
        vshort: 0,
        vushort: 0,
        vint: 0,
        vuint: 0,
        vfloat: 0.0,
        vdouble: 0.0,
        vbool: false,
        disable_int_compression: false,
    };

    if !binn_object_next(iter, pkey, &mut value) {
        return std::ptr::null_mut();
    }

    if let Some(ptype) = ptype {
        *ptype = value.type_;
    }

    if let Some(psize) = psize {
        *psize = value.size;
    }

    unsafe { store_value(&value) }
}

pub fn binn_load(data: *mut std::ffi::c_void, value: &mut BinnStruct) -> Bool {
    if data.is_null() || value.is_null() {
        return 0;
    }
    unsafe {
        std::ptr::write_bytes(value, 0, 1);
    }
    value.header = 0x1F22B11F;
    if binn_is_valid(data, &mut value.type_, &mut value.count, &mut value.size) == 0 {
        return 0;
    }
    value.ptr = data;
    return 1;
}

