pub fn binn_map_read_pair(
    ptr: *const std::ffi::c_void,
    pos: i32,
    pid: Option<&mut i32>,
    ptype: Option<&mut i32>,
    psize: Option<&mut i32>,
) -> Option<*mut std::ffi::c_void> {
    let mut value = BinnStruct {
        header: 0,
        allocated: false,
        writable: false,
        dirty: false,
        pbuf: std::ptr::null_mut(),
        pre_allocated: false,
        alloc_size: 0,
        used_size: 0,
        type_: 0,
        ptr: std::ptr::null_mut(),
        size: 0,
        count: 0,
        freefn: None,
        vint8: 0,
        vint16: 0,
        vint32: 0,
        vint64: 0,
        vuint8: 0,
        vuint16: 0,
        vuint32: 0,
        vuint64: 0,
        vchar: 0,
        vuchar: 0,
        vshort: 0,
        vushort: 0,
        vint: 0,
        vuint: 0,
        vfloat: 0.0,
        vdouble: 0.0,
        vbool: false,
        disable_int_compression: false,
    };

    if !binn_map_get_pair(ptr, pos, pid, &mut value) {
        return None;
    }

    if let Some(ptype) = ptype {
        *ptype = value.type_;
    }

    if let Some(psize) = psize {
        *psize = value.size;
    }

    unsafe { Some(store_value(&value)) }
}

