pub fn binn_open(data: *mut c_void) -> Option<*mut BinnStruct> {
    let item: *mut BinnStruct = binn_malloc(std::mem::size_of::<BinnStruct>()) as *mut BinnStruct;
    if item.is_null() {
        return None;
    }

    if !binn_load(data, unsafe { &mut *item }) {
        if let Some(free_fn) = unsafe { free_fn } {
            free_fn(item as *mut c_void);
        }
        return None;
    }

    unsafe {
        (*item).allocated = true;
    }
    Some(item)
}

