    match binn_type {
        0xE0 => binn_list_add(item, type_, pvalue, size),
        0xE1 => binn_map_set(item, id, type_, pvalue, size),
        0xE2 => binn_object_set(item, name, type_, pvalue, size),
        _ => 0,
    }
}

pub fn binn_list_add_new(list: &mut BinnStruct, value: &BinnStruct) -> Bool {
    let retval = binn_list_add_value(list, value);
    unsafe {
        if !value.ptr.is_null() {
            if let Some(free_fn) = free_fn {
                free_fn(value.ptr);
            }
        }
    }
    retval
}

pub fn binn_object_set_new(obj: &mut BinnStruct, key: &str, value: Option<&BinnStruct>) -> Bool {
    let retval = binn_object_set_value(obj, key, value.unwrap_or(&BinnStruct::default()));
    if let Some(value) = value {
        unsafe {
            if let Some(free_fn) = free_fn {
                free_fn(value as *const BinnStruct as *mut c_void);
            }
        }
    }
    retval
}

pub fn binn_map_set_new(map: &mut BinnStruct, id: i32, value: &BinnStruct) -> Bool {
    let retval = binn_map_set_value(map, id, value);
    unsafe {
        if let Some(free_fn) = free_fn {
            free_fn(value as *const _ as *mut std::ffi::c_void);
        }
    }
    retval
}
